create table if not exists public.lab_test_catalog(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,group_name text not null,test_name text not null,rate numeric(12,2) not null default 0 check(rate>=0),parameters jsonb not null default '[]'::jsonb,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create unique index if not exists lab_test_catalog_user_name_uq on public.lab_test_catalog(user_id,lower(trim(test_name)));create table if not exists public.lab_results(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,patient_id uuid not null references public.patients(id) on delete cascade,test_id uuid not null references public.lab_test_catalog(id) on delete restrict,values jsonb not null default '{}'::jsonb,status text not null default 'draft' check(status in ('draft','verified','printed')),technician_name text,verifier_name text,report_no text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(patient_id,test_id));alter table public.lab_test_catalog enable row level security;alter table public.lab_results enable row level security;create policy lab_catalog_select on public.lab_test_catalog for select to authenticated using(active=true or exists(select 1 from public.user_profiles u where u.id=auth.uid() and u.active=true and u.role='admin'));create policy lab_catalog_admin_insert on public.lab_test_catalog for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.user_profiles u where u.id=auth.uid() and u.active=true and u.role='admin'));create policy lab_catalog_admin_update on public.lab_test_catalog for update to authenticated using(user_id=auth.uid() and exists(select 1 from public.user_profiles u where u.id=auth.uid() and u.active=true and u.role='admin')) with check(user_id=auth.uid());create policy lab_results_select on public.lab_results for select to authenticated using(user_id=auth.uid());create policy lab_results_insert on public.lab_results for insert to authenticated with check(user_id=auth.uid());create policy lab_results_update on public.lab_results for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create or replace function public.bootstrap_lab_catalog() returns jsonb language plpgsql security definer set search_path=public as $$declare a uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;select id into a from public.user_profiles where role='admin' and active=true order by created_at limit 1;if a is null then raise exception 'No active ADMIN account';end if;insert into public.lab_test_catalog(user_id,group_name,test_name,rate,parameters)select a,v.g,v.n,v.r,v.p::jsonb from(values('Haematology','CBC',500,'[{"name":"Haemoglobin","unit":"g/dL","ref":"Male 13-17; Female 12-15"},{"name":"WBC Count","unit":"/µL","ref":"4000-11000"},{"name":"Platelet Count","unit":"/µL","ref":"150000-450000"},{"name":"RBC Count","unit":"million/µL","ref":"Male 4.5-5.9; Female 4.1-5.1"},{"name":"MCV","unit":"fL","ref":"80-100"},{"name":"MCH","unit":"pg","ref":"27-33"},{"name":"MCHC","unit":"g/dL","ref":"32-36"},{"name":"ESR","unit":"mm/hr","ref":"Male 0-15; Female 0-20"}'),('Biochemistry','Lipid Profile',800,'[{"name":"Total Cholesterol","unit":"mg/dL","ref":"<200"},{"name":"Triglycerides","unit":"mg/dL","ref":"<150"},{"name":"HDL Cholesterol","unit":"mg/dL","ref":">40"},{"name":"LDL Cholesterol","unit":"mg/dL","ref":"<100"},{"name":"VLDL","unit":"mg/dL","ref":"5-40"}'),('Biochemistry','Serum Creatinine',400,'[{"name":"Creatinine","unit":"mg/dL","ref":"Male 0.7-1.3; Female 0.6-1.1"}'),('Biochemistry','Blood Glucose (Fasting)',300,'[{"name":"Glucose","unit":"mg/dL","ref":"70-99"}'),('Serology','CRP',350,'[{"name":"CRP","unit":"mg/L","ref":"<5"}'),('Urine R/E','Urine R/E',300,'[{"name":"Colour","unit":"","ref":"Pale yellow"},{"name":"Appearance","unit":"","ref":"Clear"},{"name":"Protein","unit":"","ref":"Negative"},{"name":"Glucose","unit":"","ref":"Negative"},{"name":"RBC","unit":"/HPF","ref":"0-2"},{"name":"Pus Cells","unit":"/HPF","ref":"0-5"}'),('Urine M/E','Urine M/E',300,'[{"name":"RBC","unit":"/HPF","ref":"0-2"},{"name":"Pus Cells","unit":"/HPF","ref":"0-5"},{"name":"Epithelial Cells","unit":"/HPF","ref":"Few"},{"name":"Bacteria","unit":"","ref":"Absent"}'),('Immunology','TSH',500,'[{"name":"TSH","unit":"µIU/mL","ref":"0.4-4.0"}'))v(g,n,r,p)where not exists(select 1 from public.lab_test_catalog x where x.user_id=a and lower(trim(x.test_name))=lower(trim(v.n)));return jsonb_build_object('ok',true);end$$;revoke all on function public.bootstrap_lab_catalog() from public;grant execute on function public.bootstrap_lab_catalog() to authenticated;